local GreaveArmorer = {}
local PRODUCTS = {
    simple_iron_greaves = { name = "Preproste železne gležnjarice", ironCost = 3, leatherCost = 1, time = 5, cost = 150, defense = 22, happiness = 1, description = "Preproste železne gležnjarice za vojake." },
    steel_shin_greaves = { name = "Jeklene golenice", ironCost = 2, steelCost = 2, leatherCost = 1, time = 7, cost = 380, defense = 35, happiness = 1, prestige = 3, description = "Jeklene golenice za viteze." },
    silver_trimmed_greaves = { name = "Srebrnoobrobljene golenice", ironCost = 2, steelCost = 2, silverCost = 1, leatherCost = 1, time = 10, cost = 820, defense = 48, happiness = 2, prestige = 8, description = "Srebrnoobrobljene golenice za plemiške viteze." },
    gold_embossed_greaves = { name = "Zlatoizbočene golenice", ironCost = 2, steelCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, time = 14, cost = 1800, defense = 60, happiness = 3, prestige = 18, description = "Zlatoizbočene golenice za visoke plemiče." },
    jewel_set_greaves = { name = "Draguljaste golenice", ironCost = 2, steelCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 18, cost = 3800, defense = 72, happiness = 5, prestige = 32, description = "Golenice z draguljem za visoko plemstvo." },
    royal_grand_greaves = { name = "Kraljevski velike golenice", ironCost = 4, steelCost = 3, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 7500, defense = 88, happiness = 12, prestige = 62, description = "Velike kraljevske golenice z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    greave_workshop = { name = "Golenična delavnica", cost = { gold = 260, wood = 100, stone = 140, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    armor_loft = { name = "Oklepna podstrešje", cost = { gold = 1000, wood = 260, stone = 320, steel = 6, leather = 6 }, upkeep = 24, qualityBonus = 18 },
    master_armorer_atelier = { name = "Mojstrski okleparski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_greave_palace = { name = "Kraljevska golenična palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
GreaveArmorer.ironStock = 16; GreaveArmorer.steelStock = 10; GreaveArmorer.leatherStock = 10; GreaveArmorer.silverStock = 6; GreaveArmorer.goldStock = 6; GreaveArmorer.jewelStock = 4; GreaveArmorer.pearlStock = 4
GreaveArmorer.productStock = {}; GreaveArmorer.buildings = {}; GreaveArmorer.maker = nil; GreaveArmorer.activeMaking = {}; GreaveArmorer.totalProducts = 0; GreaveArmorer.dayTimer = 0
function GreaveArmorer.init() GreaveArmorer.ironStock=16; GreaveArmorer.steelStock=10; GreaveArmorer.leatherStock=10; GreaveArmorer.silverStock=6; GreaveArmorer.goldStock=6; GreaveArmorer.jewelStock=4; GreaveArmorer.pearlStock=4; GreaveArmorer.productStock={}; GreaveArmorer.buildings={}; GreaveArmorer.maker=nil; GreaveArmorer.activeMaking={}; GreaveArmorer.totalProducts=0; GreaveArmorer.dayTimer=0; print("[GreaveArmorer] Royal Greave Armorer System initialized (6 products, 4 buildings)") end
function GreaveArmorer.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GreaveArmorer.maker={name=n or ("Goleničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Goleničar najet: %s (spretnost: %d)",GreaveArmorer.maker.name,s),"success") end; return true end
function GreaveArmorer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GreaveArmorer.build(id) local ok,e=GreaveArmorer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GreaveArmorer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GreaveArmorer.getQualityBonus() local b=0; for _,bd in ipairs(GreaveArmorer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GreaveArmorer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GreaveArmorer.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and GreaveArmorer.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.leatherCost and GreaveArmorer.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GreaveArmorer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GreaveArmorer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GreaveArmorer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GreaveArmorer.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GreaveArmorer.buildings==0 then return false,"Potrebna golenična delavnica" end; if not GreaveArmorer.maker then return false,"Potreben goleničar" end; return true end
function GreaveArmorer.make(pt,qty) qty=qty or 1; local ok,e=GreaveArmorer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GreaveArmorer.ironStock=GreaveArmorer.ironStock-d.ironCost*qty end; if d.steelCost then GreaveArmorer.steelStock=GreaveArmorer.steelStock-d.steelCost*qty end; if d.leatherCost then GreaveArmorer.leatherStock=GreaveArmorer.leatherStock-d.leatherCost*qty end; if d.silverCost then GreaveArmorer.silverStock=GreaveArmorer.silverStock-d.silverCost*qty end; if d.goldCost then GreaveArmorer.goldStock=GreaveArmorer.goldStock-d.goldCost*qty end; if d.jewelCost then GreaveArmorer.jewelStock=GreaveArmorer.jewelStock-d.jewelCost*qty end; if d.pearlCost then GreaveArmorer.pearlStock=GreaveArmorer.pearlStock-d.pearlCost*qty end; local t=d.time; if GreaveArmorer.maker then t=math.max(1,t-math.floor(GreaveArmorer.maker.skill/12)) end; table.insert(GreaveArmorer.activeMaking,{id="greave_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GreaveArmorer.completeMaking(m) local q=1.0+(GreaveArmorer.getQualityBonus()/100); if GreaveArmorer.maker then q=q+(GreaveArmorer.maker.skill/140) end; q=math.min(2.5,q); GreaveArmorer.productStock[m.productType]=(GreaveArmorer.productStock[m.productType] or 0)+m.quantity; GreaveArmorer.totalProducts=GreaveArmorer.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GreaveArmorer.maker then GreaveArmorer.maker.itemsMade=GreaveArmorer.maker.itemsMade+m.quantity; if math.random()<0.25 then GreaveArmorer.maker.skill=math.min(100,GreaveArmorer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Golenice izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"greave.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function GreaveArmorer.update(dt) if not _G.state then return end; GreaveArmorer.dayTimer=GreaveArmorer.dayTimer+dt; if GreaveArmorer.dayTimer>=30 then GreaveArmorer.dayTimer=0; for i=#GreaveArmorer.activeMaking,1,-1 do local m=GreaveArmorer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GreaveArmorer.completeMaking(m); table.remove(GreaveArmorer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GreaveArmorer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GreaveArmorer.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GreaveArmorer.getStats() return {ironStock=GreaveArmorer.ironStock,steelStock=GreaveArmorer.steelStock,leatherStock=GreaveArmorer.leatherStock,silverStock=GreaveArmorer.silverStock,goldStock=GreaveArmorer.goldStock,jewelStock=GreaveArmorer.jewelStock,pearlStock=GreaveArmorer.pearlStock,productStock=GreaveArmorer.productStock,numBuildings=#GreaveArmorer.buildings,hasMaker=GreaveArmorer.maker~=nil,makerName=GreaveArmorer.maker and GreaveArmorer.maker.name or "—",makerSkill=GreaveArmorer.maker and GreaveArmorer.maker.skill or 0,activeMaking=#GreaveArmorer.activeMaking,totalProducts=GreaveArmorer.totalProducts} end
return GreaveArmorer
